package com.jiugeng.erp.watch;
import static com.jiugeng.erp.watch.WatchTypes.*;
import java.sql.*;import java.time.Instant;import java.util.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;
@Repository class WatchRepository{
 private final JdbcClient jdbc;WatchRepository(JdbcClient jdbc){this.jdbc=jdbc;}
 void lockStore(String id){jdbc.sql("SELECT id FROM watch_store WHERE id=:id FOR UPDATE").param("id",id).query(String.class).optional().orElseThrow(()->new WatchException(404,"WATCH_STORE_NOT_FOUND","店铺不存在"));}
 void lockEvent(String id){jdbc.sql("SELECT id FROM watch_new_product_event WHERE id=:id FOR UPDATE").param("id",id).query(String.class).optional().orElseThrow(()->new WatchException(404,"WATCH_EVENT_NOT_FOUND","事件不存在"));}
 Set<String> previouslySeen(String id){return new HashSet<>(jdbc.sql("SELECT DISTINCT a.asin FROM watch_snapshot_asin a JOIN watch_run r ON r.id=a.run_id WHERE r.store_id=:id AND r.decision='PROMOTED'").param("id",id).query(String.class).list());}
 List<StoreView> stores(){return jdbc.sql("SELECT * FROM watch_store WHERE removed=FALSE ORDER BY store_name,store_key_normalized").query(this::mapStore).list();}
 Optional<String> removedId(String key){return jdbc.sql("SELECT id FROM watch_store WHERE store_key_normalized=:key AND removed=TRUE").param("key",normalize(key)).query(String.class).optional();}
 void restore(String id){lockStore(id);jdbc.sql("UPDATE watch_store SET removed=FALSE,status='ACTIVE',version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id AND removed=TRUE").param("id",id).update();}
 Optional<StoreView> store(String id){return jdbc.sql("SELECT * FROM watch_store WHERE id=:id").param("id",id).query(this::mapStore).optional();}
 void insertStore(String id,String key,String name,String url,String actor){jdbc.sql("INSERT INTO watch_store (id,store_key,store_key_normalized,store_name,source_url,created_by) VALUES (:id,:key,:normalized,:name,:url,:actor)").param("id",id).param("key",key).param("normalized",normalize(key)).param("name",name).param("url",url).param("actor",actor).update();}
 Optional<StoredRun> runByRequest(String requestId){return jdbc.sql("SELECT id,store_id,payload_hash,decision FROM watch_run WHERE request_id=:request").param("request",requestId).query((r,n)->new StoredRun(r.getString("id"),r.getString("store_id"),r.getString("payload_hash"),r.getString("decision"))).optional();}
 void insertRun(String id,String storeId,String requestId,String hash,String status,int itemCount,int uniqueCount,int pages,boolean complete,String contentHash,String integrity,String decision,String reason,Instant completed,String actor){jdbc.sql("""
 INSERT INTO watch_run (id,store_id,request_id,payload_hash,adapter_name,adapter_version,run_status,item_count,unique_asin_count,page_count,pages_complete,content_sha256,integrity_status,decision,reason_code,completed_at,created_by)
 VALUES (:id,:store,:request,:hash,'manual-snapshot','1.0',:status,:items,:uniqueCount,:pages,:complete,:contentHash,:integrity,:decision,:reason,:completed,:actor)
 """).param("id",id).param("store",storeId).param("request",requestId).param("hash",hash).param("status",status).param("items",itemCount).param("uniqueCount",uniqueCount).param("pages",pages).param("complete",complete).param("contentHash",contentHash).param("integrity",integrity).param("decision",decision).param("reason",reason).param("completed",completed).param("actor",actor).update();}
 void insertSnapshot(String runId,Set<String> asins){for(String asin:asins)jdbc.sql("INSERT INTO watch_snapshot_asin (run_id,asin) VALUES (:run,:asin)").param("run",runId).param("asin",asin).update();}
 Set<String> baseline(String storeId){return new LinkedHashSet<>(jdbc.sql("SELECT asin FROM watch_baseline_asin WHERE store_id=:store ORDER BY asin").param("store",storeId).query(String.class).list());}
 void promoteBaseline(String storeId,String runId,Set<String> asins){jdbc.sql("DELETE FROM watch_baseline_asin WHERE store_id=:store").param("store",storeId).update();for(String asin:asins)jdbc.sql("INSERT INTO watch_baseline_asin (store_id,asin,source_run_id) VALUES (:store,:asin,:run)").param("store",storeId).param("asin",asin).param("run",runId).update();jdbc.sql("UPDATE watch_store SET baseline_run_id=:run,updated_at=CURRENT_TIMESTAMP WHERE id=:store").param("run",runId).param("store",storeId).update();}
 void insertEvent(String id,String eventKey,String storeId,String runId,String asin,String title,Instant at){jdbc.sql("INSERT INTO watch_new_product_event (id,event_key,store_id,detected_run_id,asin,title,first_detected_at) VALUES (:id,:key,:store,:run,:asin,:title,:at)").param("id",id).param("key",eventKey).param("store",storeId).param("run",runId).param("asin",asin).param("title",title).param("at",at).update();}
 List<EventView> events(){return jdbc.sql("SELECT e.*,s.store_name FROM watch_new_product_event e JOIN watch_store s ON s.id=e.store_id ORDER BY e.first_detected_at DESC,e.id").query(this::mapEvent).list();}
 List<EventView> eventsForRun(String runId){return jdbc.sql("SELECT e.*,s.store_name FROM watch_new_product_event e JOIN watch_store s ON s.id=e.store_id WHERE e.detected_run_id=:run ORDER BY e.asin").param("run",runId).query(this::mapEvent).list();}
 Optional<EventView> event(String id){return jdbc.sql("SELECT e.*,s.store_name FROM watch_new_product_event e JOIN watch_store s ON s.id=e.store_id WHERE e.id=:id").param("id",id).query(this::mapEvent).optional();}
 void confirm(String id,String candidateId,String actor){jdbc.sql("UPDATE watch_new_product_event SET status='CONFIRMED',version=version+1,candidate_id=:candidate,confirmed_at=CURRENT_TIMESTAMP,confirmed_by=:actor WHERE id=:id AND status='PENDING_REVIEW'").param("candidate",candidateId).param("actor",actor).param("id",id).update();}
 RunView run(String id){return jdbc.sql("SELECT * FROM watch_run WHERE id=:id").param("id",id).query(this::mapRun).single();}
 private StoreView mapStore(ResultSet r,int n)throws SQLException{String id=r.getString("id");var last=jdbc.sql("SELECT * FROM watch_run WHERE store_id=:id ORDER BY completed_at DESC,id DESC LIMIT 1").param("id",id).query(this::mapRun).optional();String baseline=r.getString("baseline_run_id");int count=baseline==null?0:jdbc.sql("SELECT COUNT(*) FROM watch_baseline_asin WHERE store_id=:id").param("id",id).query(Integer.class).single();return new StoreView(id,r.getString("store_key"),r.getString("store_name"),r.getString("source_url"),r.getString("status"),baseline,count,last.map(RunView::id).orElse(null),last.map(RunView::status).orElse(null),last.map(RunView::integrityStatus).orElse(null),last.map(RunView::decision).orElse(null),last.map(RunView::reasonCode).orElse(null),last.map(RunView::completedAt).orElse(null),r.getLong("version"),r.getString("owner_name"),r.getString("remark"),r.getTimestamp("created_at").toInstant());}
 private RunView mapRun(ResultSet r,int n)throws SQLException{return new RunView(r.getString("id"),r.getString("store_id"),r.getString("request_id"),r.getString("run_status"),r.getString("integrity_status"),r.getString("decision"),r.getString("reason_code"),r.getInt("item_count"),r.getInt("unique_asin_count"),r.getInt("page_count"),r.getBoolean("pages_complete"),r.getTimestamp("completed_at").toInstant());}
 private EventView mapEvent(ResultSet r,int n)throws SQLException{return new EventView(r.getString("id"),r.getString("store_id"),r.getString("store_name"),r.getString("asin"),r.getString("title"),r.getTimestamp("first_detected_at").toInstant(),r.getString("detected_run_id"),r.getBoolean("ignored")?"IGNORED":r.getString("status"),r.getString("candidate_id"),r.getLong("version"),r.getString("ignore_reason"),r.getString("novelty_status"),r.getString("available_date"),r.getString("novelty_reason"),r.getTimestamp("novelty_checked_at")==null?null:r.getTimestamp("novelty_checked_at").toInstant(),r.getString("novelty_override"),r.getLong("novelty_version"));}
 static String normalize(String v){return v.trim().toUpperCase(Locale.ROOT);}
}
